import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1785319710000}`),a={name:`guide/installation.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h1><p>Sudoku is available as a universal app on the App Store, supporting iPhone, iPad, and Mac with a single purchase.</p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to “Download”">​</a></h2><ul><li><strong>App Store</strong>: <a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">Download Sudoku</a> — universal app for iPhone, iPad &amp; Mac</li></ul><h3 id="app-store-recommended" tabindex="-1">App Store (Recommended) <a class="header-anchor" href="#app-store-recommended" aria-label="Permalink to “App Store (Recommended)”">​</a></h3><p>The App Store version provides automatic updates and seamless integration across all your Apple devices.</p><ul><li><strong>App Store ID</strong>: 6793606018</li><li><strong>Link</strong>: <a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793606018</a></li><li><strong>Platforms</strong>: iPhone, iPad, Mac (universal app)</li><li><strong>Price</strong>: Check the App Store listing for current pricing</li></ul><h2 id="installation-steps" tabindex="-1">Installation Steps <a class="header-anchor" href="#installation-steps" aria-label="Permalink to “Installation Steps”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>Open the <strong>App Store</strong> on your device</li><li>Search for &quot;Sudoku&quot; or use the direct link above</li><li>Tap <strong>Get</strong> or <strong>Buy</strong> to download</li><li>The app will install automatically</li><li>Launch Sudoku from your Home Screen</li></ol><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ol><li>Open the <strong>App Store</strong> on your Mac</li><li>Search for &quot;Sudoku&quot; or use the direct link above</li><li>Click <strong>Get</strong> or <strong>Buy</strong> to purchase</li><li>The app will automatically download and install</li><li>Launch Sudoku from your Applications folder or Launchpad</li></ol><h2 id="first-launch" tabindex="-1">First Launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to “First Launch”">​</a></h2><p>When you launch Sudoku for the first time, it will request permission to access iCloud (for sync) and Game Center (for leaderboards and achievements). These are optional — the game works fully offline without them.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to “Updates”">​</a></h2><p>Updates are handled automatically by the App Store. To check for updates manually, open the App Store and go to your <strong>Account → Updates</strong> section.</p><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to “Uninstall”">​</a></h2><h3 id="iphone-ipad-1" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad-1" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>Press and hold the Sudoku app icon</li><li>Tap <strong>Remove App</strong> → <strong>Delete App</strong></li></ol><h3 id="mac-1" tabindex="-1">Mac <a class="header-anchor" href="#mac-1" aria-label="Permalink to “Mac”">​</a></h3><ol><li>Quit Sudoku</li><li>Drag <code>Sudoku.app</code> from <code>Applications</code> to the Trash</li><li>(Optional) Remove app data:</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to “System Requirements”">​</a></h2><ul><li><strong>iPhone/iPad</strong>: iOS/iPadOS 16.0 or later</li><li><strong>Mac</strong>: macOS 15.0 (Sequoia) or later</li><li><strong>CPU</strong>: Apple Silicon (M-series)</li><li><strong>Memory</strong>: 2GB minimum</li><li><strong>Storage</strong>: ~50 MB</li><li><strong>Network</strong>: Not required for gameplay (iCloud/Game Center optional)</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><p>If you encounter issues during installation:</p><ul><li><strong>macOS blocks the app</strong>: Open <strong>System Settings → Privacy &amp; Security</strong> and click <strong>Open Anyway</strong> for Sudoku</li><li><strong>App not appearing</strong>: Restart the App Store app or your device and try again</li></ul><p>For more help, visit the <a href="./troubleshooting.html">Troubleshooting guide</a> or open an issue on the project repository.</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};